use std::collections::HashMap;

/// ISO 32000-1 Base 14 Font Dictionary Mappings
pub const BASE_14_FONTS: [&str; 14] = [
    "Courier", "Courier-Bold", "Courier-Oblique", "Courier-BoldOblique",
    "Helvetica", "Helvetica-Bold", "Helvetica-Oblique", "Helvetica-BoldOblique",
    "Times-Roman", "Times-Bold", "Times-Italic", "Times-BoldItalic",
    "Symbol", "ZapfDingbats"
];

pub struct PDFCryptographicContext {
    pub cipher_mode: String,
    pub key_length: u32,
    pub padding_scheme: String,
    pub is_fips_compliant: bool,
}

pub struct AcroFormWidget {
    pub field_type: String,
    pub rect: [f32; 4],
    pub value: String,
    pub is_read_only: bool,
}

pub trait DigitalSignaturePKI {
    fn sign_document(&self, document_bytes: &[u8], cert_path: &str, password: &str) -> Result<Vec<u8>, String>;
    fn verify_signature(&self, document_bytes: &[u8]) -> Result<bool, String>;
}

